fn spirv_val() -> Option<std::path::PathBuf> {
    ["/usr/bin/spirv-val", "/usr/local/bin/spirv-val"].iter().map(std::path::PathBuf::from).find(|p| p.exists())
}

/// The user data a case is compiled with (the image cases carry their own).
fn case_user_data(c: &RefCase) -> Vec<u32> {
    if let Some(m) = image::by_name(c.name) {
        return m.user_data.to_vec();
    }
    c.user_data()
}

/// Compile one case to SPIR-V and validate it.
fn compile_case(c: &RefCase, features: Features, validator: Option<&std::path::Path>) -> Result<Vec<u32>, String> {
    compile_case_runs(c, features, validator, super::exec_run_minimum())
}

/// [`compile_case`] grouping vector-write runs of at least `runs` (0: off).
fn compile_case_runs(c: &RefCase, features: Features, validator: Option<&std::path::Path>, runs: usize) -> Result<Vec<u32>, String> {
    compile_case_split(c, features, validator, runs, None)
}

/// [`compile_case_runs`]; `split`: split every qualifying wave64 program
/// (`Some(native shuffles)`) instead of the environment's choice.
fn compile_case_split(c: &RefCase, features: Features, validator: Option<&std::path::Path>, runs: usize, split: Option<bool>) -> Result<Vec<u32>, String> {
    compile_case_full(c, features, validator, runs, split).map(|out| out.spirv)
}

/// The reflection of `c` compiled with `features`.
fn compile_reflection(c: &RefCase, features: Features) -> Result<crate::pipeline::compiler::ShaderReflection, String> {
    compile_case_full(c, features, None, super::exec_run_minimum(), None).map(|out| out.reflection)
}

fn compile_case_full(
    c: &RefCase,
    features: Features,
    validator: Option<&std::path::Path>,
    runs: usize,
    split: Option<bool>,
) -> Result<crate::pipeline::compiler::CompiledShader, String> {
    let bytes: Vec<u8> = c.code.iter().flat_map(|w| w.to_le_bytes()).collect();
    let program = decode_blob(&bytes, CODE_ADDRESS).map_err(|e| format!("decode: {e}"))?;
    let wave = c.compute.wave_size;
    let user = BindingLayout::collect_user_data_registers(&program, 0, 64);
    let gds = BindingLayout::uses_global_data_share(&program);
    let shader_base = BindingLayout::reads_shader_base(&program);
    let plan = ShaderResourcePlan::extract(program, ShaderStage::Compute, 1, 0, 64, None, wave).map_err(|e| format!("plan: {e:?}"))?;
    let user_data = case_user_data(c);
    let initial = c.initial;
    let code = c.code;
    let read = move |a: u64| -> Option<u32> {
        if a % 4 != 0 {
            return None;
        }
        if let Some(off) = a.checked_sub(CODE_ADDRESS) {
            return code.get((off / 4) as usize).copied();
        }
        Some(initial.get((a / 4) as usize).copied().unwrap_or(0))
    };
    let mut inputs = ResourceRuntimeInputs::new(&user_data, CODE_ADDRESS);
    inputs.read_memory = Some(&read);
    let (_, spec) = materialize(&plan, &inputs).map_err(|e| format!("materialize: {e:?}"))?;
    let resources = apply_specialization(&plan, &spec).map_err(|e| format!("specialize: {e}"))?;
    let flat = ShaderCompileRequest::requires_flattened_table(&plan, &resources);
    let layout = BindingLayout::allocate(&resources.info, user, gds, flat, shader_base, 0, false, false).map_err(|e| format!("layout: {e}"))?;
    let mut r = ShaderCompileRequest::new(&plan, resources, layout);
    r.wave_size = wave;
    let t = c.compute.threads;
    r.local_size = [t[0].max(1), t[1].max(1), t[2].max(1)];
    r.local_data_share_dwords = c.compute.lds_dwords;
    let mut reg = c.compute.workgroup_register;
    let mut axes = [None; 3];
    for (axis, slot) in axes.iter_mut().enumerate() {
        if c.compute.group_id[axis] {
            *slot = Some(reg);
            reg += 1;
        }
    }
    r.compute_system_registers = Some(ComputeSystemRegisters {
        work_group_x: axes[0],
        work_group_y: axes[1],
        work_group_z: axes[2],
        thread_group_size: c.compute.tg_size_en.then_some(reg),
    });
    let mut compiler = SpirvCompiler::new(features, None);
    compiler.exec_run_minimum = runs;
    if let Some(native) = split {
        compiler.set_wave64_split(true, native);
    }
    let out = compiler.compile_mesh_request(ShaderStage::Compute, &r, 0, None).map_err(|e| format!("compile: {e}"))?;
    if let Some(val) = validator {
        static SEQ: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
        let seq = SEQ.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        let tmp = std::env::temp_dir().join(format!("rps5e-ref-{}-{seq}-{}.spv", std::process::id(), c.name));
        let bytes: Vec<u8> = out.spirv.iter().flat_map(|w| w.to_le_bytes()).collect();
        std::fs::write(&tmp, bytes).map_err(|e| e.to_string())?;
        let o = std::process::Command::new(val).arg("--target-env").arg("vulkan1.3").arg(&tmp).output().map_err(|e| e.to_string())?;
        if !o.status.success() {
            return Err(format!("spirv-val ({}): {}", tmp.display(), String::from_utf8_lossy(&o.stderr).lines().take(4).collect::<Vec<_>>().join(" | ")));
        }
        let _ = std::fs::remove_file(&tmp);
    }
    Ok(out)
}

pub(crate) fn all_cases() -> Vec<&'static RefCase> {
    let mut v = Vec::new();
    for list in [buffer::all(), control::all(), image::all(), int16::all(), lds::all(), more::all(), scalar::all(), vector::all()] {
        v.extend(list);
    }
    v
}

const FEATURES: Features = Features { barycentric: true, demote: true, subgroup_size: 32, subgroup64_compute: false, max_compute_workgroup_subgroups: 32, max_shared_bytes: 49152, sample_offset: false, image_int64_atomics: true, shared_int64_atomics: true, compute_derivatives: true, compute_derivatives_linear: true, preserve_inf_nan: [true; 3], denorm_preserve: [true; 3], denorm_flush_to_zero32: true, f16_rte: false, device_clock: Some(crate::clock::DeviceClock { num: 1, den: 10 }), subgroup_clock: true, bindless_tables: true, no_float64: false, amd_proprietary: false, emit: super::EmitOptions::ALL };

/// Cases the back-end does not compile, with the reason.
const KNOWN_UNSUPPORTED: &[(&str, &str)] = &[];

/// Whether a module has an instruction with `opcode`.
fn has_op(spirv: &[u32], opcode: rspirv::spirv::Op) -> bool {
    let mut i = 5;
    while i < spirv.len() {
        let w = spirv[i];
        if w & 0xFFFF == opcode as u32 {
            return true;
        }
        i += ((w >> 16) as usize).max(1);
    }
    false
}

fn declares_capability(spirv: &[u32], capability: rspirv::spirv::Capability) -> bool {
    let mut i = 5;
    while i < spirv.len() {
        let w = spirv[i];
        if w & 0xFFFF == rspirv::spirv::Op::Capability as u32 && spirv.get(i + 1) == Some(&(capability as u32)) {
            return true;
        }
        i += ((w >> 16) as usize).max(1);
    }
    false
}

fn case(name: &str) -> &'static RefCase {
    all_cases().into_iter().find(|c| c.name == name).unwrap_or_else(|| panic!("no case {name}"))
}

/// The case's program computes in f64: it is refused without shaderFloat64.
pub(crate) fn refused_without_float64(c: &RefCase) -> bool {
    compile_case(c, Features { no_float64: true, ..FEATURES }, None).is_err_and(|e| e.contains("shaderFloat64"))
}

/// Instructions some cases must (not) compile to.
#[test]
fn ref_case_instructions() {
    use rspirv::spirv::Op;
    let checks: &[(&str, &[Op], &[Op])] = &[
        // Explicit-LOD gathers pick a per-mip view on the GPU.
        ("ImageGatherExplicitLod", &[Op::ImageGather, Op::ImageSampleExplicitLod, Op::Switch], &[]),
        ("ImageGatherLodPerLane", &[Op::ImageGather, Op::Switch], &[]),
        // A 1D gather samples two texels instead.
        ("ImageGather2DInstructionWith1DDescriptor", &[Op::ImageQuerySizeLod, Op::ImageSampleExplicitLod], &[Op::ImageGather]),
        ("ImageAtomicAdd64GlcAndExec", &[Op::ImageTexelPointer, Op::AtomicIAdd], &[]),
        ("BufferAtomicAndX2GlcAndExec", &[Op::AtomicAnd], &[]),
        ("DsAddU64Bounds", &[Op::AtomicIAdd], &[]),
        ("ImageSampleAndGather", &[Op::ImageQueryLod], &[]),
        ("BufferLoadFormatXGpuSelectedDescriptors", &[Op::Switch, Op::ConvertUToPtr], &[]),
        // Irreducible control flow runs through a dispatcher loop.
        ("DispatcherIrreducibleControlFlow", &[Op::LoopMerge], &[]),
        ("ScalarSubvectorLoopsWave64", &[Op::LoopMerge], &[]),
    ];
    for &(name, required, forbidden) in checks {
        let spirv = compile_case(case(name), FEATURES, spirv_val().as_deref()).unwrap_or_else(|e| panic!("{name}: {e}"));
        for &op in required {
            assert!(has_op(&spirv, op), "{name}: no {op:?}");
        }
        for &op in forbidden {
            assert!(!has_op(&spirv, op), "{name}: has {op:?}");
        }
    }
}

/// The image operands mask of every `OpImageGather` in a module.
fn gather_operand_masks(spirv: &[u32]) -> Vec<u32> {
    let mut masks = Vec::new();
    let mut i = 5;
    while i < spirv.len() {
        let w = spirv[i];
        let n = ((w >> 16) as usize).max(1);
        if w & 0xFFFF == rspirv::spirv::Op::ImageGather as u32 {
            // Result type, result, sampled image, coordinate, component,
            // then the optional operands mask.
            masks.push(if n > 6 { spirv[i + 6] } else { 0 });
        }
        i += n;
    }
    masks
}

/// image_gather4h reads four horizontally adjacent texels: a gather with
/// constant offsets (-1, 0), (0, 0), (1, 0), (2, 0), not a plain gather.
#[test]
fn horizontal_gather_uses_const_offsets() {
    use rspirv::spirv::ImageOperands;
    let c = case("ImageSampleAndGather");
    let plain = compile_case(c, FEATURES, spirv_val().as_deref()).unwrap();
    assert!(gather_operand_masks(&plain).iter().all(|m| m & ImageOperands::CONST_OFFSETS.bits() == 0));
    // Its image_gather4_lz (MIMG 0x47) of the 2D image as image_gather4h.
    let mut code = c.code.to_vec();
    let at = code.iter().position(|&w| w >> 26 == 0x3C && ((w >> 18) & 0x7F) == 0x47).expect("an image_gather4_lz");
    code[at] = (code[at] & !(0x7F << 18)) | (0x61 << 18);
    let horizontal = RefCase { code: Box::leak(code.into_boxed_slice()), ..*c };
    let spirv = compile_case(&horizontal, FEATURES, spirv_val().as_deref()).unwrap();
    let masks = gather_operand_masks(&spirv);
    assert!(masks.iter().any(|m| m & ImageOperands::CONST_OFFSETS.bits() != 0), "no gather with constant offsets: {masks:?}");
}

/// The image operands mask of every `OpImageSample*` in a module.
fn sample_operand_masks(spirv: &[u32]) -> Vec<u32> {
    use rspirv::spirv::Op;
    let mut masks = Vec::new();
    let mut i = 5;
    while i < spirv.len() {
        let w = spirv[i];
        let n = ((w >> 16) as usize).max(1);
        let op = w & 0xFFFF;
        // Result type, result, sampled image, coordinate (and the depth
        // reference), then the optional operands mask.
        let at = if [Op::ImageSampleImplicitLod, Op::ImageSampleExplicitLod].iter().any(|&o| o as u32 == op) {
            Some(5)
        } else if [Op::ImageSampleDrefImplicitLod, Op::ImageSampleDrefExplicitLod].iter().any(|&o| o as u32 == op) {
            Some(6)
        } else {
            None
        };
        if let Some(at) = at {
            masks.push(if n > at { spirv[i + at] } else { 0 });
        }
        i += n;
    }
    masks
}

/// A sample whose texel offset is a constant takes native ConstOffset
/// operands, without the coordinate shift (size query) of a run-time
/// offset on devices without sample Offset operands.
#[test]
fn constant_sample_offsets_are_const_offsets() {
    use rspirv::spirv::{ImageOperands, Op};
    let spirv = compile_case(case("ImageSampleA16OffsetKeepsTexelOffset32BitOnGpu"), FEATURES, spirv_val().as_deref()).unwrap();
    let masks = sample_operand_masks(&spirv);
    assert!(masks.iter().any(|m| m & ImageOperands::CONST_OFFSET.bits() != 0), "no sample with a constant offset: {masks:?}");
    assert!(!has_op(&spirv, Op::ImageQuerySizeLod), "the constant offset still shifts the coordinates");
}

/// A compute program's FLAT accesses route the shared and private
/// apertures by address and keep the device-address path for the rest.
#[test]
fn flat_apertures_route_lds_scratch_and_device() {
    use rspirv::spirv::Op;
    for name in ["FlatStackApertures32", "FlatStackApertures64"] {
        let spirv = compile_case(case(name), FEATURES, spirv_val().as_deref()).unwrap_or_else(|e| panic!("{name}: {e}"));
        // Unaligned aperture stores merge their bytes into LDS atomically;
        // device addresses go through the page table.
        assert!(has_op(&spirv, Op::AtomicOr), "{name}: no LDS byte merge");
        assert!(has_op(&spirv, Op::ConvertUToPtr), "{name}: no device-address path");
    }
}

/// Without device support the 64-bit atomics are reported, not emitted.
#[test]
fn int64_atomics_need_device_support() {
    let none = Features { image_int64_atomics: false, shared_int64_atomics: false, ..FEATURES };
    assert!(compile_case(case("ImageAtomicAdd64GlcAndExec"), none, None).is_err());
    assert!(compile_case(case("DsAddU64Bounds"), none, None).is_err());
    // With it, the module declares what the atomics use: a 64-bit buffer
    // atomic Int64Atomics, a 64-bit image atomic also Int64ImageEXT.
    use rspirv::spirv::Capability;
    let buffer = compile_case(case("BufferAtomicAndX2GlcAndExec"), FEATURES, None).unwrap();
    assert!(declares_capability(&buffer, Capability::Int64Atomics), "buffer_atomic_and_x2 without Int64Atomics");
    let image = compile_case(case("ImageAtomicAdd64GlcAndExec"), FEATURES, None).unwrap();
    assert!(declares_capability(&image, Capability::Int64Atomics), "64-bit image atomic without Int64Atomics");
    assert!(declares_capability(&image, Capability::Int64ImageEXT), "64-bit image atomic without Int64ImageEXT");
    // Without compute derivatives the LOD query reads 0.
    let plain = Features { compute_derivatives: false, ..FEATURES };
    let spirv = compile_case(case("ImageSampleAndGather"), plain, spirv_val().as_deref()).unwrap();
    assert!(!has_op(&spirv, rspirv::spirv::Op::ImageQueryLod));
}

/// The scope constants of every `OpReadClockKHR` in a module.
fn clock_scopes(spirv: &[u32]) -> Vec<u32> {
    use rspirv::spirv::Op;
    let mut consts = std::collections::HashMap::new();
    let mut scopes = Vec::new();
    let mut i = 5;
    while i < spirv.len() {
        let w = spirv[i];
        let n = ((w >> 16) as usize).max(1);
        let ops = &spirv[i + 1..(i + n).min(spirv.len())];
        if w & 0xFFFF == Op::Constant as u32 && ops.len() == 3 {
            consts.insert(ops[1], ops[2]);
        }
        if w & 0xFFFF == Op::ReadClockKHR as u32 {
            scopes.push(ops[2]);
        }
        i += n;
    }
    scopes.iter().map(|s| consts.get(s).copied().unwrap_or(u32::MAX)).collect()
}

/// `s_memrealtime` reads the device clock (device scope) scaled to the
/// reference clock when the device has a calibrated one, else an
/// initialised per-invocation counter; `s_memtime` reads the subgroup
/// clock.
#[test]
fn realtime_clock_reads_the_device_clock() {
    use rspirv::spirv::{Op, Scope};
    let c = case("ScalarMemRealtimeCapturedPlaceholder");
    let on = compile_case(c, FEATURES, spirv_val().as_deref()).unwrap();
    assert_eq!(clock_scopes(&on), vec![Scope::Device as u32; 2]);
    assert!(has_op(&on, Op::UDiv) && has_op(&on, Op::UMod));
    let off = compile_case(c, Features { device_clock: None, subgroup_clock: false, ..FEATURES }, spirv_val().as_deref()).unwrap();
    assert!(!has_op(&off, Op::ReadClockKHR));
    // s_memtime (SMEM opcode 0x24) with the subgroup clock.
    let mut code = c.code.to_vec();
    for i in [0, 10] {
        assert_eq!(code[i], 0xf4940300);
        code[i] = 0xf4900300;
    }
    let memtime = RefCase { code: Box::leak(code.into_boxed_slice()), ..*c };
    let sub = compile_case(&memtime, FEATURES, spirv_val().as_deref()).unwrap();
    assert_eq!(clock_scopes(&sub), vec![Scope::Subgroup as u32; 2]);
}

/// Whether a module declares `capability` and an `OpExecutionMode` of
/// `mode` with operand `width`.
fn float_controls(spirv: &[u32], capability: rspirv::spirv::Capability, mode: rspirv::spirv::ExecutionMode, width: u32) -> (bool, bool) {
    use rspirv::spirv::Op;
    let (mut cap, mut exec_mode) = (false, false);
    let mut i = 5;
    while i < spirv.len() {
        let w = spirv[i];
        let n = ((w >> 16) as usize).max(1);
        let ops = &spirv[i + 1..(i + n).min(spirv.len())];
        if w & 0xFFFF == Op::Capability as u32 && ops.first() == Some(&(capability as u32)) {
            cap = true;
        }
        if w & 0xFFFF == Op::ExecutionMode as u32 && ops.get(1) == Some(&(mode as u32)) && ops.get(2) == Some(&width) {
            exec_mode = true;
        }
        i += n;
    }
    (cap, exec_mode)
}

/// With device support every module keeps f32 signed zeros, infinities and
/// NaNs (float controls); without it neither the capability nor the mode
/// is declared.
#[test]
fn signed_zero_inf_nan_preserve_follows_the_device() {
    use rspirv::spirv::{Capability, ExecutionMode};
    let c = case("ImageSampleAndGather");
    let on = compile_case(c, FEATURES, spirv_val().as_deref()).unwrap();
    assert_eq!(float_controls(&on, Capability::SignedZeroInfNanPreserve, ExecutionMode::SignedZeroInfNanPreserve, 32), (true, true));
    let off = compile_case(c, Features { preserve_inf_nan: [false; 3], ..FEATURES }, spirv_val().as_deref()).unwrap();
    assert_eq!(float_controls(&off, Capability::SignedZeroInfNanPreserve, ExecutionMode::SignedZeroInfNanPreserve, 32), (false, false));
}

/// With every run of two or more vector writes grouped under an EXEC
/// branch, every reference case still compiles to valid SPIR-V, and some
/// get the branches.
#[test]
fn ref_cases_with_exec_runs_compile_to_spirv() {
    let validator = spirv_val();
    let mut failures = Vec::new();
    let mut branched = 0;
    let count = |spirv: &[u32]| {
        let mut n = 0;
        let mut i = 5;
        while i < spirv.len() {
            n += (spirv[i] & 0xFFFF == rspirv::spirv::Op::SelectionMerge as u32) as usize;
            i += ((spirv[i] >> 16) as usize).max(1);
        }
        n
    };
    for c in all_cases() {
        if KNOWN_UNSUPPORTED.iter().any(|(n, _)| *n == c.name) {
            continue;
        }
        match (compile_case_runs(c, FEATURES, validator.as_deref(), 2), compile_case_runs(c, FEATURES, None, 0)) {
            (Ok(grouped), Ok(plain)) => branched += (count(&grouped) > count(&plain)) as usize,
            (Err(e), _) | (_, Err(e)) => failures.push(format!("{}: {e}", c.name)),
        }
    }
    for f in &failures {
        eprintln!("{f}");
    }
    assert!(failures.is_empty(), "{} reference cases failed", failures.len());
    assert!(branched > 0, "no reference case grouped a run");
}

/// Every reference case compiles to valid SPIR-V.
/// `cargo test -p ps5gpu --lib ref_cases_compile_to_spirv -- --nocapture`
#[test]
fn ref_cases_compile_to_spirv() {
    let validator = spirv_val();
    let cases = all_cases();
    assert_eq!(cases.len(), 583);
    let mut failures = Vec::new();
    let mut skipped = 0;
    for c in &cases {
        if let Err(e) = compile_case(c, FEATURES, validator.as_deref()) {
            if KNOWN_UNSUPPORTED.iter().any(|(n, _)| *n == c.name) {
                skipped += 1;
            } else {
                failures.push(format!("{}: {e}", c.name));
            }
        }
    }
    for f in &failures {
        eprintln!("{f}");
    }
    eprintln!("compiled {} of {} reference cases ({skipped} known unsupported)", cases.len() - failures.len() - skipped, cases.len());
    assert!(failures.is_empty(), "{} reference cases failed", failures.len());
}

/// Every wave64 reference case that qualifies compiles split over two
/// 32-wide host subgroups to valid SPIR-V, with shuffles in the half on the
/// host subgroup and with every shuffle through workgroup memory; at least
/// the ballot and lane-read cases exchange words (a workgroup barrier).
#[test]
fn ref_cases_compile_split_to_spirv() {
    let validator = spirv_val();
    let mut failures = Vec::new();
    let mut barriers = 0;
    for c in all_cases() {
        if c.compute.wave_size != 64 {
            continue;
        }
        for native in [true, false] {
            match compile_case_split(c, FEATURES, validator.as_deref(), super::exec_run_minimum(), Some(native)) {
                Ok(spirv) => barriers += has_op(&spirv, rspirv::spirv::Op::ControlBarrier) as usize,
                Err(e) => failures.push(format!("{} (native shuffles {native}): {e}", c.name)),
            }
        }
    }
    for f in &failures {
        eprintln!("{f}");
    }
    assert!(failures.is_empty(), "{} reference cases failed", failures.len());
    assert!(barriers > 20, "only {barriers} split modules exchange words");
}

/// The wave64 lane-mask projection a split program gets keeps the
/// interpreter's result of every wave64 reference case it runs, and
/// removes inverse ballots from some.
#[test]
fn wave64_mask_projection_keeps_every_case_result() {
    use ps5shader::ssa::{Op, SystemValue};
    let (mut ran, mut projected) = (0, 0);
    let mut failures = Vec::new();
    for c in all_cases() {
        if c.compute.wave_size != 64 || c.compile_only {
            continue;
        }
        let Ok(f) = c.compile(true) else { continue };
        let words = c.expected.len();
        let Ok(want) = c.execute_function(&f, words, &mut harness::Env::default()) else { continue };
        let mut g = f.clone();
        if ps5shader::opt::wave64_masks::project_wave64_lane_masks(&mut g, Some(SystemValue::HelperInvocation)) > 0 {
            ps5shader::opt::fold::cse(&mut g);
            ps5shader::opt::fold::fold(&mut g);
            ps5shader::opt::dce::dce(&mut g);
            projected += 1;
        }
        if let Err(e) = ps5shader::ssa::verify::verify(&g, true) {
            failures.push(format!("{}: {e}", c.name));
            continue;
        }
        ran += 1;
        let inverse = |f: &ps5shader::ssa::Function| f.order.iter().flat_map(|&b| f.block(b).insts.iter()).filter(|&&v| f.op(v) == Op::InverseBallot).count();
        assert!(inverse(&g) <= inverse(&f), "{}", c.name);
        match c.execute_function(&g, words, &mut harness::Env::default()) {
            Ok(got) if got == want => {}
            Ok(got) => {
                let diff = got.iter().zip(&want).filter(|(a, b)| a != b).count();
                failures.push(format!("{}: {diff} words differ", c.name));
            }
            Err(e) => failures.push(format!("{}: {e}", c.name)),
        }
    }
    assert!(failures.is_empty(), "{failures:#?}");
    assert!(ran > 100 && projected > 10, "{ran} cases ran, {projected} projected");
}

/// A device that can require 64-wide subgroups runs wave64 compute
/// programs one lane per invocation on them: the module asks for 64 and
/// keeps the guest's work-group size.
#[test]
fn wave64_compute_requires_64_wide_subgroups_where_the_device_can() {
    let c = case("Wave64CrossHalfLaneAndLds");
    let wide = Features { subgroup64_compute: true, ..FEATURES };
    compile_case(c, wide, spirv_val().as_deref()).unwrap();
    let r = compile_reflection(c, wide).unwrap();
    assert_eq!(r.local_size, [c.compute.threads[0].max(1), c.compute.threads[1].max(1), c.compute.threads[2].max(1)]);
    assert_eq!(r.required_subgroup_size, 64);
    let narrow = compile_reflection(c, FEATURES).unwrap();
    assert_eq!(narrow.required_subgroup_size, 0);
}

/// Whether a module declares execution mode `mode` with literal `bits`.
fn has_mode_bits(spirv: &[u32], mode: rspirv::spirv::ExecutionMode, bits: u32) -> bool {
    let mut i = 5;
    while i < spirv.len() {
        let w = spirv[i];
        let n = ((w >> 16) as usize).max(1);
        if w & 0xFFFF == rspirv::spirv::Op::ExecutionMode as u32 && spirv.get(i + 2) == Some(&(mode as u32)) && spirv.get(i + 3) == Some(&bits) {
            return true;
        }
        i += n;
    }
    false
}

/// Where the device guarantees round-to-nearest-even 16-bit floats, the
/// f32 -> f16 conversions are native (OpFConvert under the 16-bit
/// RoundingModeRTE mode) instead of the integer conversion; every
/// reference case still compiles and validates.
#[test]
fn native_f16_conversions_under_rounding_mode_rte() {
    use rspirv::spirv::{ExecutionMode, Op};
    let native = Features { f16_rte: true, ..FEATURES };
    let validator = spirv_val();
    let mut failures = Vec::new();
    let (mut converted, mut shorter) = (0, 0u32);
    for c in all_cases() {
        let spirv = match compile_case(c, native, validator.as_deref()) {
            Ok(s) => s,
            Err(e) => {
                failures.push(format!("{}: {e}", c.name));
                continue;
            }
        };
        if !has_mode_bits(&spirv, ExecutionMode::RoundingModeRTE, 16) {
            continue;
        }
        converted += 1;
        assert!(has_mode_bits(&spirv, ExecutionMode::DenormPreserve, 16), "{}: no 16-bit DenormPreserve", c.name);
        assert!(has_op(&spirv, Op::FConvert), "{}: no native conversion", c.name);
        let plain = compile_case(c, FEATURES, None).unwrap();
        assert!(!has_mode_bits(&plain, ExecutionMode::RoundingModeRTE, 16), "{}: RoundingModeRTE without the feature", c.name);
        shorter += (spirv.len() < plain.len()) as u32;
    }
    assert!(failures.is_empty(), "{failures:#?}");
    assert!(converted >= 5 && shorter >= 5, "only {converted} cases convert to f16 natively, {shorter} of them shorter");
}

/// Whether a module decorates some id with `d`.
fn has_decoration(spirv: &[u32], d: rspirv::spirv::Decoration) -> bool {
    let mut i = 5;
    while i < spirv.len() {
        let w = spirv[i];
        let n = ((w >> 16) as usize).max(1);
        if w & 0xFFFF == rspirv::spirv::Op::Decorate as u32 && n >= 3 && spirv[i + 2] == d as u32 {
            return true;
        }
        i += n;
    }
    false
}

/// buffer_gl0_inv / buffer_gl1_inv (captured encodings) are a device-scope
/// acquire of buffer and image memory, once per guest wave, with no
/// workgroup barrier; the program's buffer views become Coherent.
#[test]
fn vector_cache_invalidation_is_an_acquire() {
    use rspirv::spirv::Op;
    let c = case("BufferLoadStore");
    let plain = compile_case(c, FEATURES, spirv_val().as_deref()).unwrap();
    assert!(!has_op(&plain, Op::MemoryBarrier));
    let mut code = vec![0xE1C4_0000, 0, 0xBF8C_0000, 0xE1C8_0000, 0, 0xBF8C_0000];
    code.extend_from_slice(c.code);
    let inv = RefCase { code: Box::leak(code.into_boxed_slice()), ..*c };
    let spirv = compile_case(&inv, FEATURES, spirv_val().as_deref()).unwrap();
    let mut consts = std::collections::HashMap::new();
    let mut barriers = Vec::new();
    let mut i = 5;
    while i < spirv.len() {
        let w = spirv[i];
        let n = ((w >> 16) as usize).max(1);
        let ops = &spirv[i + 1..(i + n).min(spirv.len())];
        if w & 0xFFFF == Op::Constant as u32 && ops.len() == 3 {
            consts.insert(ops[1], ops[2]);
        }
        if w & 0xFFFF == Op::MemoryBarrier as u32 {
            barriers.push((consts[&ops[0]], consts[&ops[1]]));
        }
        i += n;
    }
    assert_eq!(barriers, vec![(1, 0x842); 2], "device scope, acquire | uniform | image memory");
    assert!(!has_op(&spirv, Op::ControlBarrier));
    assert!(has_decoration(&spirv, rspirv::spirv::Decoration::Coherent));
}

/// s_barrier in a program that stores to buffers is a workgroup
/// acquire-release of workgroup, buffer and image memory: other waves read
/// the stores made before it with plain loads after it. A program storing
/// nothing orders only workgroup memory.
#[test]
fn barrier_acquires_stored_memory() {
    use rspirv::spirv::Op;
    assert_eq!(super::emit::barrier_semantics(false, false), 0x108);
    assert_eq!(super::emit::barrier_semantics(false, true), 0x948);
    let c = case("BufferLoadStore");
    let mut code = vec![0xBF8A_0000];
    code.extend_from_slice(c.code);
    let barrier = RefCase { code: Box::leak(code.into_boxed_slice()), ..*c };
    let spirv = compile_case(&barrier, FEATURES, spirv_val().as_deref()).unwrap();
    let mut consts = std::collections::HashMap::new();
    let mut barriers = Vec::new();
    let mut i = 5;
    while i < spirv.len() {
        let w = spirv[i];
        let n = ((w >> 16) as usize).max(1);
        let ops = &spirv[i + 1..(i + n).min(spirv.len())];
        if w & 0xFFFF == Op::Constant as u32 && ops.len() == 3 {
            consts.insert(ops[1], ops[2]);
        }
        if w & 0xFFFF == Op::ControlBarrier as u32 {
            barriers.push((consts[&ops[0]], consts[&ops[1]], consts[&ops[2]]));
        }
        i += n;
    }
    assert_eq!(barriers, vec![(2, 2, 0x948)], "workgroup scope, acquire-release | uniform | workgroup | image memory");
}

/// GDS is declared Coherent (and Aliased): a wave spinning on a GDS word
/// another work-group writes must see the store (reference 0998eb4f2;
/// `ds_read_b32` / `ds_write_b32` with GDS set).
#[test]
fn gds_is_coherent() {
    const CODE: &[u32] = &[0x3400_0082, 0xBEFC_03FF, 0x0000_FFFF, 0xD8DA_0000, 0x0100_0000, 0xBF8C_C07F, 0xD836_0080, 0x0000_0100, 0xBF81_0000];
    let c = all_cases().into_iter().next().unwrap();
    let case = RefCase { code: CODE, ..*c };
    let spirv = compile_case(&case, FEATURES, spirv_val().as_deref()).unwrap();
    assert!(has_decoration(&spirv, rspirv::spirv::Decoration::Coherent));
}

/// The StorageBuffer variables of a module whose block holds a runtime
/// array of `bits`-bit integers: (binding, decorated Aliased).
fn int_array_buffers(spirv: &[u32], bits: u32) -> Vec<(u32, bool)> {
    int_array_buffer_decorations(spirv, bits).into_iter().map(|(b, aliased, _)| (b, aliased)).collect()
}

/// [`int_array_buffers`] with whether each variable is decorated Coherent.
fn int_array_buffer_decorations(spirv: &[u32], bits: u32) -> Vec<(u32, bool, bool)> {
    use rspirv::spirv::{Decoration, Op, StorageClass};
    let m = rspirv::dr::load_words(spirv).unwrap();
    let id = |i: &rspirv::dr::Instruction, k: usize| i.operands[k].unwrap_id_ref();
    let find = |r: u32| m.types_global_values.iter().find(|i| i.result_id == Some(r));
    let mut out = Vec::new();
    for v in m.types_global_values.iter().filter(|i| i.class.opcode == Op::Variable && i.operands[0].unwrap_storage_class() == StorageClass::StorageBuffer) {
        let Some(ptr) = find(v.result_type.unwrap()) else { continue };
        let mut t = find(id(ptr, 1));
        if t.is_some_and(|t| t.class.opcode == Op::TypeArray) {
            t = find(id(t.unwrap(), 0));
        }
        let Some(block) = t.filter(|t| t.class.opcode == Op::TypeStruct && !t.operands.is_empty()) else { continue };
        let Some(arr) = find(id(block, 0)).filter(|a| a.class.opcode == Op::TypeRuntimeArray) else { continue };
        let Some(elem) = find(id(arr, 0)).filter(|e| e.class.opcode == Op::TypeInt) else { continue };
        if elem.operands[0].unwrap_literal_bit32() != bits {
            continue;
        }
        let r = v.result_id.unwrap();
        let decorated = |d: Decoration| m.annotations.iter().find(|a| a.class.opcode == Op::Decorate && id(a, 0) == r && a.operands[1].unwrap_decoration() == d);
        let binding = decorated(Decoration::Binding).map_or(u32::MAX, |a| a.operands[2].unwrap_literal_bit32());
        out.push((binding, decorated(Decoration::Aliased).is_some(), decorated(Decoration::Coherent).is_some()));
    }
    out
}

/// GLC buffer loads and stores go through a Coherent view of the bound
/// buffers (an Aliased variable of the same binding, the plain view Aliased
/// too): the host's per-multiprocessor caches are not coherent, and a
/// work-group spinning on a flag its predecessor publishes kept reading a
/// stale cached word (GTA V's decoupled look-back scan hung the GPU,
/// GPU_PLAN §71). Without GLC the module has no Coherent buffer view.
#[test]
fn glc_buffer_accesses_use_a_coherent_view() {
    let c = all_cases()
        .into_iter()
        .find(|c| c.code.iter().any(|&w| is_buffer_load_dword(w) && w & (1 << 14) == 0))
        .expect("a buffer_load_dword case");
    let plain = compile_case(c, FEATURES, spirv_val().as_deref()).unwrap();
    assert!(int_array_buffer_decorations(&plain, 32).iter().all(|d| !d.2), "{}: a Coherent view without GLC", c.name);
    let code: Vec<u32> = c.code.iter().map(|&w| if is_buffer_load_dword(w) { w | (1 << 14) } else { w }).collect();
    let glc = RefCase { code: Box::leak(code.into_boxed_slice()), ..*c };
    let spirv = compile_case(&glc, FEATURES, spirv_val().as_deref()).unwrap();
    let views = int_array_buffer_decorations(&spirv, 32);
    let coherent: Vec<_> = views.iter().filter(|d| d.2).collect();
    assert_eq!(coherent.len(), 1, "{}: views {views:?}", c.name);
    let binding = coherent[0].0;
    assert!(coherent[0].1, "{}: the Coherent view is not Aliased", c.name);
    assert!(views.iter().filter(|d| d.0 == binding).all(|d| d.1), "{}: a view of binding {binding} is not Aliased: {views:?}", c.name);
}

/// A module that reaches the bound buffers through the 64-bit view as well
/// declares both views of the binding Aliased: a dword store and a qword
/// access to the same bytes stay ordered (reference d644c3185).
#[test]
fn qword_buffer_views_alias_the_dword_view() {
    let validator = spirv_val();
    let mut with_qwords = 0;
    // The buffer_load_dword cases, with the load turned into a
    // buffer_atomic_add_x2 (a qword access through the same V#).
    let atomics: Vec<RefCase> = all_cases()
        .into_iter()
        .filter(|c| c.code.iter().any(|&w| is_buffer_load_dword(w)))
        .map(|c| {
            let code: Vec<u32> = c.code.iter().map(|&w| if is_buffer_load_dword(w) { (w & !(0x7F << 18)) | (0x52 << 18) } else { w }).collect();
            RefCase { code: Box::leak(code.into_boxed_slice()), ..*c }
        })
        .collect();
    for c in all_cases().into_iter().chain(atomics.iter()) {
        let Ok(spirv) = compile_case(c, FEATURES, validator.as_deref()) else { continue };
        let dwords = int_array_buffers(&spirv, 32);
        // 64-bit views of a binding that also has a 32-bit view.
        let qwords: Vec<(u32, bool)> = int_array_buffers(&spirv, 64).into_iter().filter(|q| dwords.iter().any(|d| d.0 == q.0)).collect();
        if qwords.is_empty() {
            continue;
        }
        with_qwords += 1;
        for (binding, aliased) in qwords {
            assert!(aliased, "{}: the 64-bit view of binding {binding} is not Aliased", c.name);
            assert!(dwords.iter().filter(|d| d.0 == binding).any(|d| d.1), "{}: no Aliased 32-bit view of binding {binding}", c.name);
        }
    }
    assert!(with_qwords > 0, "no case uses the 64-bit buffer view");
}

/// Whether a module has an `OpLoad` with the Volatile memory-access bit.
fn has_volatile_load(spirv: &[u32]) -> bool {
    let mut i = 5;
    while i < spirv.len() {
        let w = spirv[i];
        let n = ((w >> 16) as usize).max(1);
        if w & 0xFFFF == rspirv::spirv::Op::Load as u32 && n >= 5 && spirv[i + 4] & rspirv::spirv::MemoryAccess::VOLATILE.bits() != 0 {
            return true;
        }
        i += n;
    }
    false
}

fn is_buffer_load_dword(w: u32) -> bool {
    w & 0xFC00_0000 == 0xE000_0000 && (w >> 18) & 0x7F == 0x0C
}

/// A GLC buffer load compiles to a volatile load (a spin on a flag another
/// work-group publishes must reload it every iteration); without GLC none.
#[test]
fn glc_buffer_loads_are_volatile() {
    let c = all_cases()
        .into_iter()
        .find(|c| c.code.iter().any(|&w| is_buffer_load_dword(w) && w & (1 << 14) == 0))
        .expect("a buffer_load_dword case");
    let plain = compile_case(c, FEATURES, spirv_val().as_deref()).unwrap();
    assert!(!has_volatile_load(&plain), "{}", c.name);
    let code: Vec<u32> = c.code.iter().map(|&w| if is_buffer_load_dword(w) { w | (1 << 14) } else { w }).collect();
    let glc = RefCase { code: Box::leak(code.into_boxed_slice()), ..*c };
    let spirv = compile_case(&glc, FEATURES, spirv_val().as_deref()).unwrap();
    assert!(has_volatile_load(&spirv), "{}", c.name);
}

/// buffer_load_format_xyz through descriptors the program selects at run
/// time (read through their device addresses; Spider-Man 2's compute
/// program 0x809673d00) compiles: every output component takes the format
/// and its destination select from the V#'s word 3. The case is
/// BufferLoadFormatXGpuSelectedDescriptors with the load widened to XYZ
/// and Y and Z stored too.
#[test]
fn runtime_format_xyz_loads_through_device_addresses_compile() {
    let c = case("BufferLoadFormatXGpuSelectedDescriptors");
    let mut code = c.code.to_vec();
    let load = code.iter().position(|&w| w == 0xe000_3000).expect("buffer_load_format_x");
    // buffer_load_format_xyz v[4:6].
    code[load] = 0xe008_3000;
    let store = code.iter().position(|&w| w == 0xe070_1000).expect("buffer_store_dword");
    // buffer_store_dword v5 / v6, v30, s[48:51] offen offset:0x100 / 0x200.
    code.splice(store + 2..store + 2, [0xe070_1100, 0x800c_051e, 0xe070_1200, 0x800c_061e]);
    // The loop branch skips the two new stores back to the loop head.
    let branch = code.iter().position(|&w| w == 0xbf85_ffef).expect("s_cbranch_scc1");
    code[branch] = 0xbf85_ffeb;
    let xyz = RefCase { code: Box::leak(code.into_boxed_slice()), ..*c };
    let spirv = compile_case(&xyz, FEATURES, spirv_val().as_deref()).unwrap();
    // One switch over the formats per load, the element read and its range
    // checked before it (248 282 words before; GTA V's compute program
    // 0x803dd3c00, five such XYZ loads, was 2.4 million words and took the
    // driver 150 s: GPU_PLAN §76).
    eprintln!("runtime-format XYZ load: {} SPIR-V words", spirv.len());
    assert!(spirv.len() < RUNTIME_XYZ_WORDS_MAX, "{} SPIR-V words", spirv.len());
}

/// The size [`runtime_format_xyz_loads_through_device_addresses_compile`]
/// stays under.
const RUNTIME_XYZ_WORDS_MAX: usize = 30_000;

/// GFX10 forms a compute quad from four consecutive lanes: an implicit-LOD
/// access of a compute program whose group holds a multiple of four
/// invocations takes linear derivative groups (on any grid, an N x 1 one
/// included), quads of a 2x2 grid only without them.
#[test]
fn compute_derivatives_group_consecutive_lanes() {
    use rspirv::spirv::{ExecutionMode, Op};
    let c = case("ImageSampleAndGather");
    // A wave64 program at two lanes per host invocation: whole waves on a
    // 2-wide grid, whose 2x2 quads are four consecutive lanes.
    let waves = compile_case(c, FEATURES, spirv_val().as_deref()).unwrap();
    assert!(has_op(&waves, Op::ImageQueryLod) && has_mode_bits_any(&waves, ExecutionMode::DerivativeGroupQuadsNV));
    // A wave32 8 x 1 group: no 2x2 quad fits, linear groups do.
    let row = RefCase { compute: Compute { threads: [8, 1, 1], wave_size: 32, ..c.compute }, ..*c };
    let linear = compile_case(&row, FEATURES, spirv_val().as_deref()).unwrap();
    assert!(has_op(&linear, Op::ImageQueryLod));
    assert!(has_mode_bits_any(&linear, ExecutionMode::DerivativeGroupLinearNV), "no linear derivative groups");
    assert!(!has_mode_bits_any(&linear, ExecutionMode::DerivativeGroupQuadsNV));
    let quads_only = Features { compute_derivatives_linear: false, ..FEATURES };
    let spirv = compile_case(&row, quads_only, spirv_val().as_deref()).unwrap();
    assert!(!has_op(&spirv, Op::ImageQueryLod), "an 8x1 group has no 2x2 quads");
    // An 8 x 8 group: linear groups, not the 2x2 quads of its grid.
    let square = RefCase { compute: Compute { threads: [8, 8, 1], wave_size: 32, ..c.compute }, ..*c };
    let spirv = compile_case(&square, FEATURES, spirv_val().as_deref()).unwrap();
    assert!(has_mode_bits_any(&spirv, ExecutionMode::DerivativeGroupLinearNV) && !has_mode_bits_any(&spirv, ExecutionMode::DerivativeGroupQuadsNV));
}

/// Whether a module declares execution mode `mode` (any operands).
fn has_mode_bits_any(spirv: &[u32], mode: rspirv::spirv::ExecutionMode) -> bool {
    let mut i = 5;
    while i < spirv.len() {
        let w = spirv[i];
        let n = ((w >> 16) as usize).max(1);
        if w & 0xFFFF == rspirv::spirv::Op::ExecutionMode as u32 && spirv.get(i + 2) == Some(&(mode as u32)) {
            return true;
        }
        i += n;
    }
    false
}

/// GDS is one memory for the whole GPU: its buffer is Coherent, so a plain
/// GDS read never returns a value cached before another work-group's write.
#[test]
fn gds_buffer_is_coherent() {
    let spirv = compile_case(case("DsGdsSubdwordAndAtomics"), FEATURES, spirv_val().as_deref()).unwrap();
    let mut i = 5;
    let mut coherent = false;
    while i < spirv.len() {
        let w = spirv[i];
        let n = ((w >> 16) as usize).max(1);
        if w & 0xFFFF == rspirv::spirv::Op::Decorate as u32 && spirv.get(i + 2) == Some(&(rspirv::spirv::Decoration::Coherent as u32)) {
            coherent = true;
        }
        i += n;
    }
    assert!(coherent, "the GDS buffer is not Coherent");
}

/// A GLC `buffer_load_dwordx2` is one 64-bit access on the hardware: it
/// is read with one 64-bit atomic load (falling back to two dword loads
/// when unaligned or out of range), so it never sees half of a
/// `buffer_atomic_*_x2` or of a coherent pair store. Without GLC it stays
/// two dword loads.
#[test]
fn coherent_dwordx2_loads_are_one_atomic_access() {
    use rspirv::spirv::Op;
    // v1 = tid * 8; buffer_atomic_add_x2 v[2:3] (1), v1, s[0:3] offen;
    // buffer_load_dwordx2 v[4:5], v1, s[0:3] offen glc; s_waitcnt;
    // buffer_store_dwordx2 v[4:5], v1, s[4:7] offen; s_endpgm.
    let program = |atomic: bool, glc: bool| -> &'static [u32] {
        let mut w = vec![0x3402_0083, 0x7E04_0281, 0x7E06_0280];
        if atomic {
            w.extend([0xE148_1000, 0x8000_0201]);
        }
        w.extend([0xE034_1000 | (glc as u32) << 14, 0x8000_0401, 0xBF8C_0000, 0xE074_1000, 0x8001_0401, 0xBF81_0000]);
        Box::leak(w.into_boxed_slice())
    };
    let base = case("BufferAtomicAndX2GlcAndExec");
    for (atomic, glc, expect) in [(true, true, true), (true, false, false), (false, true, true), (false, false, false)] {
        let c = RefCase { code: program(atomic, glc), ..*base };
        let spirv = compile_case(&c, FEATURES, spirv_val().as_deref()).unwrap();
        assert_eq!(has_op(&spirv, Op::AtomicLoad), expect, "atomic {atomic} glc {glc}");
    }
}

/// A GLC `buffer_store_dwordx2` is one 64-bit write on the hardware (a
/// work-group polling a {flag, value} pair never sees the flag without its
/// value): it is written with one 64-bit atomic store (two dword stores
/// when unaligned or out of range); without GLC it stays two dword stores
/// (reference e5b4bd72d).
#[test]
fn coherent_dwordx2_stores_are_one_atomic_access() {
    use rspirv::spirv::Op;
    // v1 = tid * 8; v[2:3] = (1, 0); buffer_store_dwordx2 v[2:3], v1,
    // s[4:7] offen (glc); s_endpgm.
    let program = |glc: bool| -> &'static [u32] {
        let w = vec![0x3402_0083, 0x7E04_0281, 0x7E06_0280, 0xE074_1000 | (glc as u32) << 14, 0x8001_0201, 0xBF81_0000];
        Box::leak(w.into_boxed_slice())
    };
    let base = case("BufferAtomicAndX2GlcAndExec");
    for glc in [true, false] {
        let c = RefCase { code: program(glc), ..*base };
        let spirv = compile_case(&c, FEATURES, spirv_val().as_deref()).unwrap();
        assert_eq!(has_op(&spirv, Op::AtomicStore), glc, "glc {glc}");
    }
}

/// Without guaranteed 16-bit round-to-nearest-even and denormals the
/// driver's f32 -> f16 conversion is not stepped toward zero: the
/// toward-zero conversion of v_cvt_pkrtz_f16_f32 is computed on the bits
/// (no OpFConvert); with the guarantee it steps from the native one.
#[test]
fn pkrtz_without_native_f16_rounding_converts_on_the_bits() {
    use rspirv::spirv::Op;
    // v1 = tid * 4; v4 = input[tid]; v_cvt_pkrtz_f16_f32 v20, v4, v4;
    // output[tid] = v20.
    static CODE: [u32; 8] = [0x3402_0082, 0xe030_1000, 0x8000_0401, 0xbf8c_3f70, (0x2F << 25) | (20 << 17) | (4 << 9) | 260, 0xe070_1000, 0x8001_1401, 0xbf81_0000];
    let c = &RefCase { code: &CODE, ..*case("CvtPkrtzF16F32SubnormalRoundsTowardZero") };
    let plain = compile_case(c, FEATURES, spirv_val().as_deref()).unwrap();
    assert!(!has_op(&plain, Op::FConvert), "a native f16 conversion without the 16-bit rounding guarantee");
    let native = compile_case(c, Features { f16_rte: true, ..FEATURES }, spirv_val().as_deref()).unwrap();
    assert!(has_op(&native, Op::FConvert));
}

/// Without shaderFloat64 every case either compiles without the Float64
/// capability (the translator's own exact conversions use integer code)
/// or is refused because its program computes in f64.
#[test]
fn no_float64_devices_refuse_only_f64_programs() {
    use rspirv::spirv::Capability;
    let no64 = Features { no_float64: true, ..FEATURES };
    let validator = spirv_val();
    let (mut refused, mut rewritten) = (Vec::new(), Vec::new());
    for c in all_cases() {
        let Ok(with) = compile_case(c, FEATURES, None) else { continue };
        let used_f64 = declares_capability(&with, Capability::Float64);
        match compile_case(c, no64, validator.as_deref()) {
            Ok(spirv) => {
                assert!(!declares_capability(&spirv, Capability::Float64), "{} declares Float64", c.name);
                if used_f64 {
                    rewritten.push(c.name);
                }
            }
            Err(e) => {
                assert!(e.contains("shaderFloat64"), "{}: {e}", c.name);
                assert!(used_f64, "{} refused without using f64", c.name);
                refused.push(c.name);
            }
        }
    }
    eprintln!("f64 programs refused: {refused:?}\nf64 only in translator code, now integer: {rewritten:?}");
    assert!(refused.iter().any(|n| n.contains("F64")));
}

/// The correctly rounded f32 of `x / (2^32 - 1)` from the exact quotient.
fn exact_unorm32(x: u32) -> u32 {
    if x == 0 {
        return 0;
    }
    let d = u32::MAX as u128;
    // Scale so that the integer quotient has 24 bits.
    let mut s = 0;
    while (x as u128) << s < d << 23 {
        s += 1;
    }
    let n = (x as u128) << s;
    let (mut m, r) = (n / d, n % d);
    if 2 * r > d || (2 * r == d && m & 1 == 1) {
        m += 1;
    }
    (m as f32 * 2f32.powi(-(s as i32))).to_bits()
}

#[test]
fn unorm32_integer_conversion_is_correctly_rounded() {
    let mut xs: Vec<u32> = vec![0, 1, 2, 3, 0x7F, 0x80, 0xFF_FFFF, 0x100_0000, 0x100_0001, 0x100_0002, 0x100_0003, 0x8000_0000, 0x8000_0080, 0x8000_0180, 0xFFFF_FF7F, 0xFFFF_FF80, 0xFFFF_FFFE, u32::MAX];
    let mut v = 0x1234_5678u32;
    for _ in 0..200_000 {
        v ^= v << 13;
        v ^= v >> 17;
        v ^= v << 5;
        xs.push(v);
        xs.push(v | 0x80 >> (v & 7));
    }
    for x in xs {
        assert_eq!(super::memory::unorm32_model(x), exact_unorm32(x), "unorm32 {x:#x}");
    }
}

/// CPU model of the integer toward-zero conversion against the f64 one
/// (step the nearest result toward zero where it rounded away).
#[test]
fn int_to_float_toward_zero_matches_the_f64_path() {
    fn integer(x: u32, signed: bool, half: bool) -> f64 {
        let p = if half { 11 } else { 24 };
        let (neg, m) = if signed && (x as i32) < 0 { (true, x.wrapping_neg()) } else { (false, x) };
        let shift = if m >= 1 << p { 31 - m.leading_zeros() - (p - 1) } else { 0 };
        let mut t = (m >> shift) << shift;
        if half {
            t = t.min(65504);
        }
        let f = if half { t as f64 } else { t as f32 as f64 };
        if neg { -f } else { f }
    }
    fn f64_path(x: u32, signed: bool, half: bool) -> f64 {
        let exact = if signed { x as i32 as f64 } else { x as f64 };
        if half {
            // Nearest f16 with ties to even, inf beyond 65520.
            let nearest = |v: f64| -> f64 {
                let a = v.abs();
                if a >= 65520.0 {
                    return f64::INFINITY.copysign(v);
                }
                let e = a.log2().floor().max(-14.0);
                let ulp = 2f64.powf(e - 10.0);
                let q = a / ulp;
                let r = q.round_ties_even() * ulp;
                r.copysign(v)
            };
            let n = if exact == 0.0 { 0.0 } else { nearest(exact) };
            if n.abs() > exact.abs() {
                // One f16 step toward zero.
                let a = n.abs();
                let below = if a.is_infinite() { 65504.0 } else { a - 2f64.powf((a.log2().ceil() - 1.0).max(-14.0) - 10.0) };
                return below.copysign(n);
            }
            return n;
        }
        let n = if signed { x as i32 as f32 } else { x as f32 };
        if (n as f64).abs() > exact.abs() {
            return f32::from_bits(n.to_bits() - 1) as f64;
        }
        n as f64
    }
    let mut xs: Vec<u32> = vec![0, 1, 0xFF_FFFF, 0x100_0000, 0x100_0001, 0x1FF_FFFF, 0x7FFF_FFFF, 0x8000_0000, 0x8000_0001, 0xFFFF_FFFF, 2047, 2048, 2049, 4095, 65503, 65504, 65519, 65520, 65535, 65536];
    let mut v = 0x9E37_79B9u32;
    for _ in 0..100_000 {
        v ^= v << 13;
        v ^= v >> 17;
        v ^= v << 5;
        xs.push(v);
        xs.push(v >> (v & 31));
    }
    for x in xs {
        for signed in [false, true] {
            assert_eq!(integer(x, signed, false), f64_path(x, signed, false), "f32 {x:#x} signed={signed}");
            assert_eq!(integer(x, signed, true), f64_path(x, signed, true), "f16 {x:#x} signed={signed}");
        }
    }
}

/// Wave32 compares, s_and_saveexec and EXEC restores keep their lane
/// masks without subgroup ballots (the reference driver's
/// Wave32ExecLaneBits; its results are checked in ps5shader's
/// hw_scalar_waves and on the device by exec_ref).
#[test]
fn wave32_exec_lane_bits_without_ballots() {
    static CODE: [u32; 17] = [
        0x340c0082, 0x7d88008d, 0x02020080, 0xbe8a3c6a, 0x4a0202c0, 0x887e0a7e, 0x7d820094, 0xbe8b3c6a, 0x4a0202a0, 0xbefe030b, 0x7d82008a, 0x7e0e0281,
        0x02040e80, 0x4a020302, 0xe0701000, 0x80000106, 0xbf810000,
    ];
    let c = RefCase {
        name: "Wave32ExecLaneBits",
        code: &CODE,
        initial: &[],
        expected: &[],
        user_data: None,
        compute: Compute { threads: [32, 1, 1], lds_dwords: 0, wave_size: 32, float_mode: 0xC0, dispatch_threads: [0; 3], workgroup_register: 0, thread_ids: 1, group_id: [false; 3], dispatch_dims: false, tg_size_en: false },
        dispatch: [1, 1, 1],
        compile_only: true,
        tolerance: 0.0,
        bda: &[],
    };
    let spirv = compile_case(&c, FEATURES, spirv_val().as_deref()).unwrap();
    assert!(!has_op(&spirv, rspirv::spirv::Op::GroupNonUniformBallot), "wave32 compares and EXEC copies emitted subgroup ballots");
}
